// @Embeddable composite key — Serializable, equals, hashCode over ALL key fields
package com.bank.statement.model;

import jakarta.persistence.Embeddable;
import java.io.Serializable;
import java.time.YearMonth;
import java.util.Objects;

@Embeddable
public class StatementId implements Serializable {

    private String accountId;
    private YearMonth period;

    protected StatementId() {}  // required no-arg ctor

    public StatementId(String accountId, YearMonth period) {
        this.accountId = accountId;
        this.period = period;
    }

    public String getAccountId() { return accountId; }
    public YearMonth getPeriod() { return period; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof StatementId that)) return false;
        return Objects.equals(accountId, that.accountId) && Objects.equals(period, that.period);
    }

    @Override
    public int hashCode() { return Objects.hash(accountId, period); }
}
