package com.bank.statement.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "monthly_statements")
public class MonthlyStatement {

    @EmbeddedId                      // composite key as ONE object
    private StatementId id;

    @Column(name = "closing_balance", nullable = false)
    private BigDecimal closingBalance;

    @Column(name = "generated_at")
    private LocalDateTime generatedAt;

    protected MonthlyStatement() {}

    public MonthlyStatement(StatementId id, BigDecimal closingBalance) {
        this.id = id;
        this.closingBalance = closingBalance;
        this.generatedAt = LocalDateTime.now();
    }

    public StatementId getId() { return id; }
    public BigDecimal getClosingBalance() { return closingBalance; }
    public LocalDateTime getGeneratedAt() { return generatedAt; }
}
