package com.bank.statement.service;

import com.bank.statement.dto.StatementView;
import com.bank.statement.model.MonthlyStatement;
import com.bank.statement.model.StatementId;
import com.bank.statement.repository.StatementRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class StatementService {

    private final StatementRepository repo;

    @Transactional
    public StatementView generate(String accountId, String period, BigDecimal closingBalance) {
        StatementId id = new StatementId(accountId, YearMonth.parse(period));
        MonthlyStatement statement = new MonthlyStatement(id, closingBalance);
        repo.save(statement);  // INSERT INTO monthly_statements (account_id, period, ...) 
        log.info("Generated statement for composite key ({}, {})", accountId, period);
        return StatementView.from(statement);
    }

    @Transactional(readOnly = true)
    public StatementView getOne(String accountId, String period) {
        StatementId id = new StatementId(accountId, YearMonth.parse(period));
        MonthlyStatement statement = repo.findById(id)  // lookup by composite key
            .orElseThrow(() -> new IllegalArgumentException("No statement for " + accountId + " " + period));
        return StatementView.from(statement);
    }

    @Transactional(readOnly = true)
    public List<StatementView> listForAccount(String accountId) {
        return repo.findByIdAccountIdOrderByIdPeriodDesc(accountId).stream()
            .map(StatementView::from).toList();
    }
}
