package com.bank.statement.controller;

import com.bank.statement.dto.StatementView;
import com.bank.statement.service.StatementService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.List;

@RestController
@RequestMapping("/api/v1/statements")
@RequiredArgsConstructor
public class StatementController {

    private final StatementService service;

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public StatementView generate(@RequestParam String accountId,
                                   @RequestParam String period,
                                   @RequestParam BigDecimal closingBalance) {
        return service.generate(accountId, period, closingBalance);
    }

    @GetMapping("/{accountId}/{period}")
    public StatementView getOne(@PathVariable String accountId, @PathVariable String period) {
        return service.getOne(accountId, period);
    }

    @GetMapping("/{accountId}")
    public List<StatementView> list(@PathVariable String accountId) {
        return service.listForAccount(accountId);
    }
}
