package com.bank.statement.model;

import org.junit.jupiter.api.Test;
import java.time.YearMonth;
import static org.assertj.core.api.Assertions.*;

class StatementIdTest {

    @Test
    void equalKeysAreEqual() {
        StatementId a = new StatementId("SAV2001", YearMonth.of(2026, 10));
        StatementId b = new StatementId("SAV2001", YearMonth.of(2026, 10));
        assertThat(a).isEqualTo(b);
        assertThat(a.hashCode()).isEqualTo(b.hashCode());
    }

    @Test
    void differentPeriodMeansDifferentKey() {
        StatementId oct = new StatementId("SAV2001", YearMonth.of(2026, 10));
        StatementId sep = new StatementId("SAV2001", YearMonth.of(2026, 9));
        assertThat(oct).isNotEqualTo(sep);
    }

    @Test
    void differentAccountMeansDifferentKey() {
        StatementId raj = new StatementId("SAV2001", YearMonth.of(2026, 10));
        StatementId pri = new StatementId("CUR3001", YearMonth.of(2026, 10));
        assertThat(raj).isNotEqualTo(pri);
    }

    @Test
    void keyIsSerializable() {
        assertThat(java.io.Serializable.class)
            .isAssignableFrom(StatementId.class); // required for composite keys
    }
}
